 /*Menmenu CSS*/

 a.meanmenu-reveal {
     display: none
 }

 .mean-container .mean-bar {
     background: 0 0;
     float: left;
     min-height: 42px;
     padding: 0;
     position: relative;
     width: 100%;
     z-index: 9
 }

 .mean-container a.meanmenu-reveal {
     color: #fff;
     cursor: pointer;
     display: block;
     float: right;
     font-family: Arial, Helvetica, sans-serif;
     font-size: 1px;
     font-weight: 700;
     height: 22px;
     line-height: 22px;
     padding: 13px 0 11px;
     right: 0;
     text-decoration: none;
     text-indent: -9999em;
     top: 0;
     width: 22px
 }

 .mean-container a.meanmenu-reveal span {
     display: block;
     background: #fff;
     height: 3px;
     margin-top: 3px
 }

 .mean-container .mean-nav {
     float: left;
     width: 100%;
     background: #0c1923
 }

 .mean-container .mean-nav ul {
     padding: 0;
     margin: 0;
     width: 100%;
     list-style-type: none
 }

 .mean-container .mean-nav ul li {
     background: #f8f8f8;
     float: left;
     position: relative;
     width: 100%;
     border-top: 1px solid #ddd
 }

 .mean-container .mean-nav ul li:first-child {
     border: 0
 }

 .mean-container .mean-nav ul li a {
     background: #f8f8f8;
     color: #666;
     display: block;
     float: left;
     font-size: 12px;
     margin: 0;
     padding: 1em 5%;
     text-align: left;
     text-decoration: none;
     text-transform: uppercase;
     width: 90%;
     font-weight: 700
 }

 .mobile-menu-area {
     background: #262626
 }

 .mean-container .mean-nav ul li li a {
     border-top: 1px solid rgba(255, 255, 255, .25);
     opacity: .75;
     padding: 1em 10%;
     text-shadow: none!important;
     visibility: visible;
     width: 80%;
     font-weight: 400;
     text-transform: capitalize;
     color: #444
 }

 .mean-container .mean-nav ul li.mean-last a {
     border-bottom: 0;
     margin-bottom: 0
 }

 .mean-container .mean-nav ul li li li a {
     width: 70%;
     padding: 1em 15%
 }

 .mean-container .mean-nav ul li li li li a {
     width: 60%;
