}
.nivo-caption a {
	display:inline !important;
}
.nivo-html-caption {
    display:none;
}
/* Direction nav styles (e.g. Next & Prev) */
.nivo-directionNav a {
	position:absolute;
	top:0;
	z-index:99;
	cursor:pointer;
}
.nivo-prevNav {
	left:0px;
}
/* Control nav styles (e.g. 1,2,3...) */
.nivo-controlNav {
